+        return CheckResult {
+            name:        "Forgejo".to_string(),
+            status:      CheckStatus::Warning,
+            summary:     "not configured".to_string(),
+            details:     Vec::new(),
+            remediation: Some(
+                "Set server.integrations.forgejo.{enabled,url} and the vault FORGEJO_TOKEN"
+                    .to_string(),
+            ),
+        };
+    };
+
+    let client = match fabro_http::test_http_client() {
+        Ok(client) => client,
+        Err(err) => {
