+                name:        "Forgejo".to_string(),
+                status:      CheckStatus::Error,
+                summary:     "failed to build HTTP client".to_string(),
+                details:     vec![CheckDetail::new(format!("{err}"))],
+                remediation: Some("Check network/proxy settings".to_string()),
+            };
