+/// Minimal repository summary the client needs.
+#[derive(Debug, Clone, Deserialize, Serialize)]
+pub struct ForgejoRepository {
+    pub full_name: String,
+    #[serde(default)]
+    pub private:   bool,
+    #[serde(default)]
+    pub fork:      bool,
+}
